<h1>مجوز آرشیو موردی</h1><p>مجوز فقط برای شکایت باز، حداکثر ۷۲ ساعت و برای ناظر مستقل صادر می‌شود. هر خواندن آرشیو در حسابرسی ثبت می‌شود.</p><section class="card"><?= $this->start('/archives/grant') ?><?= $this->field('ticket_id','شناسه پرونده شکایت') ?><?= $this->field('reviewer_id','شناسه داخلی مدیر ناظر') ?><?= $this->field('purpose','هدف دسترسی') ?><?= $this->field('hours','مدت اعتبار به ساعت (۱ تا ۷۲)','number') ?><button>صدور مجوز</button></form></section>
<?php foreach($rows as $g): ?><article class="card section"><p>پرونده: <?= $this->h($g['ticket_id']) ?></p><p>ناظر: <?= $this->h($g['reviewer_id']) ?></p><p><?= $this->h($g['purpose']) ?></p><p>وضعیت: <?= $g['revoked_at']?'لغوشده':((int)$g['expires_at']<=time()?'منقضی':'معتبر') ?></p><a href="<?= $this->h($this->url('/archive?id='.$g['booking_id'])) ?>">آرشیو (فقط ناظر دارای مجوز)</a><?= $this->start('/archives/revoke') ?><input type="hidden" name="id" value="<?= $this->h($g['id']) ?>"><button class="secondary">لغو مجوز</button></form></article><?php endforeach; ?>
